insert into public.services (slug, title, summary, description, bullets, icon, number_label, image_url, sort_order, visible) values
('interior-design','Interior Design','Thoughtful interiors that balance aesthetics, functionality and the way you live or work.','We create thoughtful interiors that balance aesthetics, functionality and the way you live or work. Our design process brings together space planning, concept development, moodboards, material selections, colour palettes, lighting and 3D visualisation to create a clear design direction for your space.',array['Space Planning','Concept Development','Moodboards & Material Selection','Colour & Finishes','Lighting Design','3D Renders & Visualisation','Furniture & Styling'],'Home','01','https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1200&q=80',1,true),
('renovation-construction','Renovation & Construction','Carefully managed renovation and construction works, from preparation to final handover.','We transform existing spaces through carefully managed renovation and construction works, combining design thinking with practical on-site execution. Whether you''re refreshing a single room or undertaking a complete property transformation, we coordinate the process from preparation and procurement to finishes and final handover.',array['Interior Renovations','Construction Management','Project Management','Procurement & Material Sourcing','Gypsum & Ceiling Works','Tiling & Flooring','Painting & Finishes','Electrical & Plumbing Coordination'],'HardHat','02','https://images.unsplash.com/photo-1503174971373-b1f69850bded?auto=format&fit=crop&w=1200&q=80',2,true),
('custom-interiors','Custom Interiors & Fittings','Bespoke elements that bring character, functionality and cohesion to your space.','We design and create custom elements that bring character, functionality and cohesion to your space. From kitchens and wardrobes to feature walls and bespoke furniture, every detail is considered to complement the overall design of your interior.',array['Custom Kitchens','Bathroom Design & Renovation','Wardrobes & Storage','Custom Furniture','TV Walls & Feature Walls','Wainscoting','Fluted & Decorative Wall Treatments'],'Armchair','03','https://images.unsplash.com/photo-1556909212-d5b604d0c90d?auto=format&fit=crop&w=1200&q=80',3,true),
('commercial-hospitality','Commercial & Hospitality Spaces','Commercial environments designed to work, feel distinctive and leave a lasting impression.','We create commercial environments that are designed to work, feel distinctive and leave a lasting impression. From offices and retail spaces to hospitality and Airbnb properties, we combine functionality, brand identity and thoughtful design to create spaces that people want to experience.',array['Office Fit-outs','Retail & Commercial Interiors','Airbnb Styling & Transformation','Hospitality Spaces','Space Planning','Interior Renovations','Custom Fixtures & Fittings'],'Building2','04','https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=80',4,true)
insert into public.testimonials (quote, name, detail, project_name, sort_order, visible) values
('Kloche understood our home better than we did. Six months on, we still notice small details they got exactly right.','Wanjiru & Kevin M.','Kileleshwa Residency','Kileleshwa Residency',1,true),
('They managed contractors, budget and our indecision with complete calm. The reveal genuinely made my mother cry.','Aisha O.','Westlands Airbnb','Westlands Airbnb',2,true),
('Our office finally feels like the studio we tell clients we are. Staff arrive earlier — that''s the review.','Daniel Kimani','Founder, Gigiri Executive Offices','Gigiri Executive Offices',3,true);
